if (I18n.lang === 'en') window.DATOS_VERSICULOS = {
  categorias: [{"id": "todas", "nombre": "All", "icono": "📖"}, {"id": "consuelo", "nombre": "Comfort in sadness", "icono": "🤗"}, {"id": "esperanza", "nombre": "Hope", "icono": "🌅"}, {"id": "gozo", "nombre": "Joy and praise", "icono": "😊"}, {"id": "ensenanza", "nombre": "Teachings", "icono": "🎓"}, {"id": "jesus", "nombre": "Words of Jesus", "icono": "✝️"}],
  versiculos: [
    {"id": 1, "cat": "consuelo", "cita": "Psalms 23:1", "libro": "Psalms", "texto": "The LORD is my shepherd; I shall not want."},
    {"id": 2, "cat": "consuelo", "cita": "Psalms 23:4", "libro": "Psalms", "texto": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."},
    {"id": 3, "cat": "consuelo", "cita": "Psalms 34:18", "libro": "Psalms", "texto": "The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit."},
    {"id": 4, "cat": "consuelo", "cita": "Psalms 46:1", "libro": "Psalms", "texto": "God is our refuge and strength, a very present help in trouble."},
    {"id": 5, "cat": "consuelo", "cita": "Psalms 55:22", "libro": "Psalms", "texto": "Cast thy burden upon the LORD , and he shall sustain thee: he shall never suffer the righteous to be moved."},
    {"id": 6, "cat": "consuelo", "cita": "Psalms 147:3", "libro": "Psalms", "texto": "He healeth the broken in heart, and bindeth up their wounds."},
    {"id": 7, "cat": "consuelo", "cita": "Psalms 30:5", "libro": "Psalms", "texto": "For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning."},
    {"id": 8, "cat": "consuelo", "cita": "Psalms 42:11", "libro": "Psalms", "texto": "Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God."},
    {"id": 9, "cat": "consuelo", "cita": "Psalms 121:1-2", "libro": "Psalms", "texto": "I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD , which made heaven and earth."},
    {"id": 10, "cat": "consuelo", "cita": "Psalms 121:7", "libro": "Psalms", "texto": "The LORD shall preserve thee from all evil: he shall preserve thy soul."},
    {"id": 11, "cat": "consuelo", "cita": "Psalms 91:1", "libro": "Psalms", "texto": "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty."},
    {"id": 12, "cat": "consuelo", "cita": "Psalms 91:11", "libro": "Psalms", "texto": "For he shall give his angels charge over thee, to keep thee in all thy ways."},
    {"id": 13, "cat": "consuelo", "cita": "Psalms 27:1", "libro": "Psalms", "texto": "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?"},
    {"id": 14, "cat": "consuelo", "cita": "Psalms 27:10", "libro": "Psalms", "texto": "When my father and my mother forsake me, then the LORD will take me up."},
    {"id": 15, "cat": "consuelo", "cita": "Psalms 56:3", "libro": "Psalms", "texto": "What time I am afraid, I will trust in thee."},
    {"id": 16, "cat": "consuelo", "cita": "Psalms 61:2", "libro": "Psalms", "texto": "From the end of the earth will I cry unto thee, when my heart is overwhelmed: lead me to the rock that is higher than I."},
    {"id": 17, "cat": "consuelo", "cita": "Psalms 62:8", "libro": "Psalms", "texto": "Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah."},
    {"id": 18, "cat": "consuelo", "cita": "Psalms 73:26", "libro": "Psalms", "texto": "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever."},
    {"id": 19, "cat": "consuelo", "cita": "Psalms 94:19", "libro": "Psalms", "texto": "In the multitude of my thoughts within me thy comforts delight my soul."},
    {"id": 20, "cat": "consuelo", "cita": "Psalms 126:5", "libro": "Psalms", "texto": "They that sow in tears shall reap in joy."},
    {"id": 21, "cat": "consuelo", "cita": "Psalms 4:8", "libro": "Psalms", "texto": "I will both lay me down in peace, and sleep: for thou, LORD , only makest me dwell in safety."},
    {"id": 22, "cat": "consuelo", "cita": "Psalms 18:2", "libro": "Psalms", "texto": "The LORD is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower."},
    {"id": 23, "cat": "consuelo", "cita": "Psalms 34:4", "libro": "Psalms", "texto": "I sought the LORD , and he heard me, and delivered me from all my fears."},
    {"id": 24, "cat": "consuelo", "cita": "Psalms 34:7", "libro": "Psalms", "texto": "The angel of the LORD encampeth round about them that fear him, and delivereth them."},
    {"id": 25, "cat": "consuelo", "cita": "Psalms 37:5", "libro": "Psalms", "texto": "Commit thy way unto the LORD ; trust also in him; and he shall bring it to pass."},
    {"id": 26, "cat": "consuelo", "cita": "Psalms 46:10", "libro": "Psalms", "texto": "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth."},
    {"id": 27, "cat": "consuelo", "cita": "Psalms 50:15", "libro": "Psalms", "texto": "And call upon me in the day of trouble: I will deliver thee, and thou shalt glorify me."},
    {"id": 28, "cat": "consuelo", "cita": "Psalms 145:18", "libro": "Psalms", "texto": "The LORD is nigh unto all them that call upon him, to all that call upon him in truth."},
    {"id": 29, "cat": "consuelo", "cita": "Psalms 103:13", "libro": "Psalms", "texto": "Like as a father pitieth his children, so the LORD pitieth them that fear him."},
    {"id": 30, "cat": "consuelo", "cita": "Isaiah 41:10", "libro": "Isaiah", "texto": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."},
    {"id": 31, "cat": "consuelo", "cita": "Isaiah 41:13", "libro": "Isaiah", "texto": "For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee."},
    {"id": 32, "cat": "consuelo", "cita": "Isaiah 43:2", "libro": "Isaiah", "texto": "When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee."},
    {"id": 33, "cat": "consuelo", "cita": "Isaiah 40:29", "libro": "Isaiah", "texto": "He giveth power to the faint; and to them that have no might he increaseth strength."},
    {"id": 34, "cat": "consuelo", "cita": "Isaiah 26:3", "libro": "Isaiah", "texto": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee."},
    {"id": 35, "cat": "consuelo", "cita": "Isaiah 49:15", "libro": "Isaiah", "texto": "Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee."},
    {"id": 36, "cat": "consuelo", "cita": "Isaiah 54:10", "libro": "Isaiah", "texto": "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee."},
    {"id": 37, "cat": "consuelo", "cita": "Isaiah 66:13", "libro": "Isaiah", "texto": "As one whom his mother comforteth, so will I comfort you; and ye shall be comforted in Jerusalem."},
    {"id": 38, "cat": "consuelo", "cita": "Joshua 1:9", "libro": "Joshua", "texto": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest."},
    {"id": 39, "cat": "consuelo", "cita": "Deuteronomy 31:6", "libro": "Deuteronomy", "texto": "Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee."},
    {"id": 40, "cat": "consuelo", "cita": "Deuteronomy 31:8", "libro": "Deuteronomy", "texto": "And the LORD , he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed."},
    {"id": 41, "cat": "consuelo", "cita": "Deuteronomy 33:27", "libro": "Deuteronomy", "texto": "The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them ."},
    {"id": 42, "cat": "consuelo", "cita": "Nahum 1:7", "libro": "Nahum", "texto": "The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him."},
    {"id": 43, "cat": "consuelo", "cita": "Lamentations 3:22-23", "libro": "Lamentations", "texto": "It is of the LORD’s mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness."},
    {"id": 44, "cat": "consuelo", "cita": "2 Corinthians 1:3", "libro": "2 Corinthians", "texto": "Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort;"},
    {"id": 45, "cat": "consuelo", "cita": "2 Corinthians 12:9", "libro": "2 Corinthians", "texto": "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me."},
    {"id": 46, "cat": "consuelo", "cita": "2 Corinthians 4:17", "libro": "2 Corinthians", "texto": "For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;"},
    {"id": 47, "cat": "consuelo", "cita": "Romans 8:28", "libro": "Romans", "texto": "And we know that all things work together for good to them that love God, to them who are the called according to his purpose."},
    {"id": 48, "cat": "consuelo", "cita": "Philippians 4:6", "libro": "Philippians", "texto": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God."},
    {"id": 49, "cat": "consuelo", "cita": "1 Peter 5:7", "libro": "1 Peter", "texto": "Casting all your care upon him; for he careth for you."},
    {"id": 50, "cat": "consuelo", "cita": "Hebrews 13:5", "libro": "Hebrews", "texto": "Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee."},
    {"id": 51, "cat": "consuelo", "cita": "Hebrews 4:16", "libro": "Hebrews", "texto": "Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need."},
    {"id": 52, "cat": "consuelo", "cita": "Zephaniah 3:17", "libro": "Zephaniah", "texto": "The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing."},
    {"id": 53, "cat": "consuelo", "cita": "Exodus 14:14", "libro": "Exodus", "texto": "The LORD shall fight for you, and ye shall hold your peace."},
    {"id": 54, "cat": "consuelo", "cita": "2 Timothy 1:7", "libro": "2 Timothy", "texto": "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind."},
    {"id": 55, "cat": "consuelo", "cita": "Psalms 32:8", "libro": "Psalms", "texto": "I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye."},
    {"id": 56, "cat": "consuelo", "cita": "Isaiah 43:1", "libro": "Isaiah", "texto": "But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine."},
    {"id": 57, "cat": "consuelo", "cita": "Psalms 28:7", "libro": "Psalms", "texto": "The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him."},
    {"id": 58, "cat": "consuelo", "cita": "Psalms 3:3", "libro": "Psalms", "texto": "But thou, O LORD , art a shield for me; my glory, and the lifter up of mine head."},
    {"id": 59, "cat": "esperanza", "cita": "Jeremiah 29:11", "libro": "Jeremiah", "texto": "For I know the thoughts that I think toward you, saith the LORD , thoughts of peace, and not of evil, to give you an expected end."},
    {"id": 60, "cat": "esperanza", "cita": "Isaiah 40:31", "libro": "Isaiah", "texto": "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."},
    {"id": 61, "cat": "esperanza", "cita": "Romans 15:13", "libro": "Romans", "texto": "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost."},
    {"id": 62, "cat": "esperanza", "cita": "Romans 5:5", "libro": "Romans", "texto": "And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us."},
    {"id": 63, "cat": "esperanza", "cita": "Romans 8:18", "libro": "Romans", "texto": "For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us."},
    {"id": 64, "cat": "esperanza", "cita": "Romans 12:12", "libro": "Romans", "texto": "Rejoicing in hope; patient in tribulation; continuing instant in prayer;"},
    {"id": 65, "cat": "esperanza", "cita": "Hebrews 11:1", "libro": "Hebrews", "texto": "Now faith is the substance of things hoped for, the evidence of things not seen."},
    {"id": 66, "cat": "esperanza", "cita": "Hebrews 10:23", "libro": "Hebrews", "texto": "Let us hold fast the profession of our faith without wavering; (for he is faithful that promised;)"},
    {"id": 67, "cat": "esperanza", "cita": "Hebrews 6:19", "libro": "Hebrews", "texto": "Which hope we have as an anchor of the soul, both sure and stedfast, and which entereth into that within the veil;"},
    {"id": 68, "cat": "esperanza", "cita": "Hebrews 9:28", "libro": "Hebrews", "texto": "So Christ was once offered to bear the sins of many; and unto them that look for him shall he appear the second time without sin unto salvation."},
    {"id": 69, "cat": "esperanza", "cita": "1 Peter 1:3", "libro": "1 Peter", "texto": "Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,"},
    {"id": 70, "cat": "esperanza", "cita": "Lamentations 3:25", "libro": "Lamentations", "texto": "The LORD is good unto them that wait for him, to the soul that seeketh him."},
    {"id": 71, "cat": "esperanza", "cita": "Lamentations 3:26", "libro": "Lamentations", "texto": "It is good that a man should both hope and quietly wait for the salvation of the LORD ."},
    {"id": 72, "cat": "esperanza", "cita": "Psalms 39:7", "libro": "Psalms", "texto": "And now, Lord, what wait I for? my hope is in thee."},
    {"id": 73, "cat": "esperanza", "cita": "Psalms 130:5", "libro": "Psalms", "texto": "I wait for the LORD , my soul doth wait, and in his word do I hope."},
    {"id": 74, "cat": "esperanza", "cita": "Proverbs 23:18", "libro": "Proverbs", "texto": "For surely there is an end; and thine expectation shall not be cut off."},
    {"id": 75, "cat": "esperanza", "cita": "Titus 2:13", "libro": "Titus", "texto": "Looking for that blessed hope, and the glorious appearing of the great God and our Saviour Jesus Christ;"},
    {"id": 76, "cat": "esperanza", "cita": "Acts 1:11", "libro": "Acts", "texto": "Which also said, Ye men of Galilee, why stand ye gazing up into heaven? this same Jesus, which is taken up from you into heaven, shall so come in like manner as ye have seen him go into heaven."},
    {"id": 77, "cat": "esperanza", "cita": "1 Thessalonians 4:16", "libro": "1 Thessalonians", "texto": "For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:"},
    {"id": 78, "cat": "esperanza", "cita": "1 Thessalonians 4:13", "libro": "1 Thessalonians", "texto": "But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope."},
    {"id": 79, "cat": "esperanza", "cita": "1 Corinthians 15:52", "libro": "1 Corinthians", "texto": "In a moment, in the twinkling of an eye, at the last trump: for the trumpet shall sound, and the dead shall be raised incorruptible, and we shall be changed."},
    {"id": 80, "cat": "esperanza", "cita": "1 Corinthians 15:55", "libro": "1 Corinthians", "texto": "O death, where is thy sting? O grave, where is thy victory?"},
    {"id": 81, "cat": "esperanza", "cita": "1 Corinthians 2:9", "libro": "1 Corinthians", "texto": "But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him."},
    {"id": 82, "cat": "esperanza", "cita": "Revelation 21:4", "libro": "Revelation", "texto": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."},
    {"id": 83, "cat": "esperanza", "cita": "Revelation 21:1", "libro": "Revelation", "texto": "And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea."},
    {"id": 84, "cat": "esperanza", "cita": "Revelation 21:5", "libro": "Revelation", "texto": "And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful."},
    {"id": 85, "cat": "esperanza", "cita": "Revelation 22:20", "libro": "Revelation", "texto": "He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus."},
    {"id": 86, "cat": "esperanza", "cita": "Revelation 1:7", "libro": "Revelation", "texto": "Behold, he cometh with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen."},
    {"id": 87, "cat": "esperanza", "cita": "Revelation 14:12", "libro": "Revelation", "texto": "Here is the patience of the saints: here are they that keep the commandments of God, and the faith of Jesus."},
    {"id": 88, "cat": "esperanza", "cita": "Isaiah 65:17", "libro": "Isaiah", "texto": "For, behold, I create new heavens and a new earth: and the former shall not be remembered, nor come into mind."},
    {"id": 89, "cat": "esperanza", "cita": "Isaiah 65:25", "libro": "Isaiah", "texto": "The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock: and dust shall be the serpent’s meat. They shall not hurt nor destroy in all my holy mountain, saith the LORD ."},
    {"id": 90, "cat": "esperanza", "cita": "Daniel 12:2", "libro": "Daniel", "texto": "And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt."},
    {"id": 91, "cat": "esperanza", "cita": "Daniel 12:3", "libro": "Daniel", "texto": "And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever."},
    {"id": 92, "cat": "esperanza", "cita": "Philippians 3:20", "libro": "Philippians", "texto": "For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:"},
    {"id": 93, "cat": "esperanza", "cita": "Philippians 1:6", "libro": "Philippians", "texto": "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:"},
    {"id": 94, "cat": "esperanza", "cita": "Colossians 3:4", "libro": "Colossians", "texto": "When Christ, who is our life, shall appear, then shall ye also appear with him in glory."},
    {"id": 95, "cat": "esperanza", "cita": "1 John 3:2", "libro": "1 John", "texto": "Beloved, now are we the sons of God, and it doth not yet appear what we shall be: but we know that, when he shall appear, we shall be like him; for we shall see him as he is."},
    {"id": 96, "cat": "esperanza", "cita": "2 Peter 3:13", "libro": "2 Peter", "texto": "Nevertheless we, according to his promise, look for new heavens and a new earth, wherein dwelleth righteousness."},
    {"id": 97, "cat": "esperanza", "cita": "2 Peter 3:9", "libro": "2 Peter", "texto": "The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance."},
    {"id": 98, "cat": "esperanza", "cita": "James 5:8", "libro": "James", "texto": "Be ye also patient; stablish your hearts: for the coming of the Lord draweth nigh."},
    {"id": 99, "cat": "esperanza", "cita": "Job 19:25", "libro": "Job", "texto": "For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth:"},
    {"id": 100, "cat": "esperanza", "cita": "Isaiah 25:8", "libro": "Isaiah", "texto": "He will swallow up death in victory; and the Lord GOD will wipe away tears from off all faces; and the rebuke of his people shall he take away from off all the earth: for the LORD hath spoken it ."},
    {"id": 101, "cat": "esperanza", "cita": "Isaiah 25:9", "libro": "Isaiah", "texto": "And it shall be said in that day, Lo, this is our God; we have waited for him, and he will save us: this is the LORD ; we have waited for him, we will be glad and rejoice in his salvation."},
    {"id": 102, "cat": "esperanza", "cita": "Micah 7:7", "libro": "Micah", "texto": "Therefore I will look unto the LORD ; I will wait for the God of my salvation: my God will hear me."},
    {"id": 103, "cat": "esperanza", "cita": "Habakkuk 2:3", "libro": "Habakkuk", "texto": "For the vision is yet for an appointed time, but at the end it shall speak, and not lie: though it tarry, wait for it; because it will surely come, it will not tarry."},
    {"id": 104, "cat": "esperanza", "cita": "Isaiah 40:8", "libro": "Isaiah", "texto": "The grass withereth, the flower fadeth: but the word of our God shall stand for ever."},
    {"id": 105, "cat": "esperanza", "cita": "Isaiah 9:6", "libro": "Isaiah", "texto": "For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace."},
    {"id": 106, "cat": "esperanza", "cita": "Malachi 4:2", "libro": "Malachi", "texto": "But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall."},
    {"id": 107, "cat": "esperanza", "cita": "Psalms 27:14", "libro": "Psalms", "texto": "Wait on the LORD : be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD ."},
    {"id": 108, "cat": "esperanza", "cita": "Isaiah 46:4", "libro": "Isaiah", "texto": "And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you ."},
    {"id": 109, "cat": "esperanza", "cita": "Ephesians 3:20", "libro": "Ephesians", "texto": "Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"},
    {"id": 110, "cat": "esperanza", "cita": "2 Corinthians 4:16", "libro": "2 Corinthians", "texto": "For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day."},
    {"id": 111, "cat": "esperanza", "cita": "Revelation 22:5", "libro": "Revelation", "texto": "And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever."},
    {"id": 112, "cat": "esperanza", "cita": "Isaiah 53:5", "libro": "Isaiah", "texto": "But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."},
    {"id": 113, "cat": "esperanza", "cita": "Psalms 31:24", "libro": "Psalms", "texto": "Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD ."},
    {"id": 114, "cat": "esperanza", "cita": "Romans 6:23", "libro": "Romans", "texto": "For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord."},
    {"id": 115, "cat": "esperanza", "cita": "Isaiah 35:4", "libro": "Isaiah", "texto": "Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you."},
    {"id": 116, "cat": "esperanza", "cita": "1 John 5:11-12", "libro": "1 John", "texto": "And this is the record, that God hath given to us eternal life, and this life is in his Son. He that hath the Son hath life; and he that hath not the Son of God hath not life."},
    {"id": 117, "cat": "gozo", "cita": "Psalms 47:1", "libro": "Psalms", "texto": "O clap your hands, all ye people; shout unto God with the voice of triumph."},
    {"id": 118, "cat": "gozo", "cita": "Psalms 118:24", "libro": "Psalms", "texto": "This is the day which the LORD hath made; we will rejoice and be glad in it."},
    {"id": 119, "cat": "gozo", "cita": "Psalms 16:11", "libro": "Psalms", "texto": "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore."},
    {"id": 120, "cat": "gozo", "cita": "Psalms 100:1-2", "libro": "Psalms", "texto": "Make a joyful noise unto the LORD , all ye lands. Serve the LORD with gladness: come before his presence with singing."},
    {"id": 121, "cat": "gozo", "cita": "Psalms 100:4", "libro": "Psalms", "texto": "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name."},
    {"id": 122, "cat": "gozo", "cita": "Psalms 100:5", "libro": "Psalms", "texto": "For the LORD is good; his mercy is everlasting; and his truth endureth to all generations."},
    {"id": 123, "cat": "gozo", "cita": "Psalms 150:6", "libro": "Psalms", "texto": "Let every thing that hath breath praise the LORD . Praise ye the LORD ."},
    {"id": 124, "cat": "gozo", "cita": "Psalms 103:1-2", "libro": "Psalms", "texto": "Bless the LORD , O my soul: and all that is within me, bless his holy name. Bless the LORD , O my soul, and forget not all his benefits:"},
    {"id": 125, "cat": "gozo", "cita": "Psalms 126:3", "libro": "Psalms", "texto": "The LORD hath done great things for us; whereof we are glad."},
    {"id": 126, "cat": "gozo", "cita": "Psalms 30:11", "libro": "Psalms", "texto": "Thou hast turned for me my mourning into dancing: thou hast put off my sackcloth, and girded me with gladness;"},
    {"id": 127, "cat": "gozo", "cita": "Psalms 32:11", "libro": "Psalms", "texto": "Be glad in the LORD , and rejoice, ye righteous: and shout for joy, all ye that are upright in heart."},
    {"id": 128, "cat": "gozo", "cita": "Psalms 34:1", "libro": "Psalms", "texto": "I will bless the LORD at all times: his praise shall continually be in my mouth."},
    {"id": 129, "cat": "gozo", "cita": "Psalms 34:8", "libro": "Psalms", "texto": "O taste and see that the LORD is good: blessed is the man that trusteth in him."},
    {"id": 130, "cat": "gozo", "cita": "Psalms 37:4", "libro": "Psalms", "texto": "Delight thyself also in the LORD ; and he shall give thee the desires of thine heart."},
    {"id": 131, "cat": "gozo", "cita": "Psalms 40:3", "libro": "Psalms", "texto": "And he hath put a new song in my mouth, even praise unto our God: many shall see it , and fear, and shall trust in the LORD ."},
    {"id": 132, "cat": "gozo", "cita": "Psalms 51:12", "libro": "Psalms", "texto": "Restore unto me the joy of thy salvation; and uphold me with thy free spirit."},
    {"id": 133, "cat": "gozo", "cita": "Psalms 95:1", "libro": "Psalms", "texto": "O come, let us sing unto the LORD : let us make a joyful noise to the rock of our salvation."},
    {"id": 134, "cat": "gozo", "cita": "Psalms 96:1", "libro": "Psalms", "texto": "O sing unto the LORD a new song: sing unto the LORD , all the earth."},
    {"id": 135, "cat": "gozo", "cita": "Psalms 98:4", "libro": "Psalms", "texto": "Make a joyful noise unto the LORD , all the earth: make a loud noise, and rejoice, and sing praise."},
    {"id": 136, "cat": "gozo", "cita": "Psalms 107:1", "libro": "Psalms", "texto": "O give thanks unto the LORD , for he is good: for his mercy endureth for ever."},
    {"id": 137, "cat": "gozo", "cita": "Psalms 136:1", "libro": "Psalms", "texto": "O give thanks unto the LORD ; for he is good: for his mercy endureth for ever."},
    {"id": 138, "cat": "gozo", "cita": "Psalms 145:3", "libro": "Psalms", "texto": "Great is the LORD , and greatly to be praised; and his greatness is unsearchable."},
    {"id": 139, "cat": "gozo", "cita": "Psalms 146:2", "libro": "Psalms", "texto": "While I live will I praise the LORD : I will sing praises unto my God while I have any being."},
    {"id": 140, "cat": "gozo", "cita": "Psalms 5:11", "libro": "Psalms", "texto": "But let all those that put their trust in thee rejoice: let them ever shout for joy, because thou defendest them: let them also that love thy name be joyful in thee."},
    {"id": 141, "cat": "gozo", "cita": "Psalms 9:1", "libro": "Psalms", "texto": "I will praise thee , O LORD , with my whole heart; I will shew forth all thy marvellous works."},
    {"id": 142, "cat": "gozo", "cita": "Psalms 92:1", "libro": "Psalms", "texto": "It is a good thing to give thanks unto the LORD , and to sing praises unto thy name, O most High:"},
    {"id": 143, "cat": "gozo", "cita": "Psalms 113:3", "libro": "Psalms", "texto": "From the rising of the sun unto the going down of the same the LORD’s name is to be praised."},
    {"id": 144, "cat": "gozo", "cita": "Psalms 117:1-2", "libro": "Psalms", "texto": "O praise the LORD , all ye nations: praise him, all ye people. For his merciful kindness is great toward us: and the truth of the LORD endureth for ever. Praise ye the LORD ."},
    {"id": 145, "cat": "gozo", "cita": "Psalms 19:1", "libro": "Psalms", "texto": "The heavens declare the glory of God; and the firmament sheweth his handywork."},
    {"id": 146, "cat": "gozo", "cita": "Psalms 8:1", "libro": "Psalms", "texto": "O LORD our Lord, how excellent is thy name in all the earth! who hast set thy glory above the heavens."},
    {"id": 147, "cat": "gozo", "cita": "Psalms 139:14", "libro": "Psalms", "texto": "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well."},
    {"id": 148, "cat": "gozo", "cita": "Psalms 63:3", "libro": "Psalms", "texto": "Because thy lovingkindness is better than life, my lips shall praise thee."},
    {"id": 149, "cat": "gozo", "cita": "Psalms 89:1", "libro": "Psalms", "texto": "I will sing of the mercies of the LORD for ever: with my mouth will I make known thy faithfulness to all generations."},
    {"id": 150, "cat": "gozo", "cita": "Philippians 4:4", "libro": "Philippians", "texto": "Rejoice in the Lord alway: and again I say, Rejoice."},
    {"id": 151, "cat": "gozo", "cita": "1 Thessalonians 5:16-18", "libro": "1 Thessalonians", "texto": "Rejoice evermore. Pray without ceasing. In every thing give thanks: for this is the will of God in Christ Jesus concerning you."},
    {"id": 152, "cat": "gozo", "cita": "Romans 14:17", "libro": "Romans", "texto": "For the kingdom of God is not meat and drink; but righteousness, and peace, and joy in the Holy Ghost."},
    {"id": 153, "cat": "gozo", "cita": "Galatians 5:22-23", "libro": "Galatians", "texto": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law."},
    {"id": 154, "cat": "gozo", "cita": "Proverbs 17:22", "libro": "Proverbs", "texto": "A merry heart doeth good like a medicine: but a broken spirit drieth the bones."},
    {"id": 155, "cat": "gozo", "cita": "Proverbs 15:13", "libro": "Proverbs", "texto": "A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken."},
    {"id": 156, "cat": "gozo", "cita": "Isaiah 61:10", "libro": "Isaiah", "texto": "I will greatly rejoice in the LORD , my soul shall be joyful in my God; for he hath clothed me with the garments of salvation, he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels."},
    {"id": 157, "cat": "gozo", "cita": "Isaiah 12:2", "libro": "Isaiah", "texto": "Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation."},
    {"id": 158, "cat": "gozo", "cita": "Isaiah 55:12", "libro": "Isaiah", "texto": "For ye shall go out with joy, and be led forth with peace: the mountains and the hills shall break forth before you into singing, and all the trees of the field shall clap their hands."},
    {"id": 159, "cat": "gozo", "cita": "Habakkuk 3:18", "libro": "Habakkuk", "texto": "Yet I will rejoice in the LORD , I will joy in the God of my salvation."},
    {"id": 160, "cat": "gozo", "cita": "Luke 2:10-11", "libro": "Luke", "texto": "And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord."},
    {"id": 161, "cat": "gozo", "cita": "James 1:2-3", "libro": "James", "texto": "My brethren, count it all joy when ye fall into divers temptations; Knowing this , that the trying of your faith worketh patience."},
    {"id": 162, "cat": "gozo", "cita": "1 Peter 1:8", "libro": "1 Peter", "texto": "Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory:"},
    {"id": 163, "cat": "gozo", "cita": "Colossians 3:16", "libro": "Colossians", "texto": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord."},
    {"id": 164, "cat": "gozo", "cita": "Colossians 3:17", "libro": "Colossians", "texto": "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him."},
    {"id": 165, "cat": "gozo", "cita": "Ephesians 5:20", "libro": "Ephesians", "texto": "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;"},
    {"id": 166, "cat": "gozo", "cita": "Hebrews 13:15", "libro": "Hebrews", "texto": "By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name."},
    {"id": 167, "cat": "gozo", "cita": "1 Chronicles 16:34", "libro": "1 Chronicles", "texto": "O give thanks unto the LORD ; for he is good; for his mercy endureth for ever."},
    {"id": 168, "cat": "gozo", "cita": "Psalms 4:7", "libro": "Psalms", "texto": "Thou hast put gladness in my heart, more than in the time that their corn and their wine increased."},
    {"id": 169, "cat": "gozo", "cita": "Psalms 33:1", "libro": "Psalms", "texto": "Rejoice in the LORD , O ye righteous: for praise is comely for the upright."},
    {"id": 170, "cat": "gozo", "cita": "Psalms 13:5", "libro": "Psalms", "texto": "But I have trusted in thy mercy; my heart shall rejoice in thy salvation."},
    {"id": 171, "cat": "ensenanza", "cita": "Proverbs 3:5-6", "libro": "Proverbs", "texto": "Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths."},
    {"id": 172, "cat": "ensenanza", "cita": "Proverbs 1:7", "libro": "Proverbs", "texto": "The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction."},
    {"id": 173, "cat": "ensenanza", "cita": "Proverbs 9:10", "libro": "Proverbs", "texto": "The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding."},
    {"id": 174, "cat": "ensenanza", "cita": "Proverbs 22:6", "libro": "Proverbs", "texto": "Train up a child in the way he should go: and when he is old, he will not depart from it."},
    {"id": 175, "cat": "ensenanza", "cita": "Proverbs 15:1", "libro": "Proverbs", "texto": "A soft answer turneth away wrath: but grievous words stir up anger."},
    {"id": 176, "cat": "ensenanza", "cita": "Proverbs 16:3", "libro": "Proverbs", "texto": "Commit thy works unto the LORD , and thy thoughts shall be established."},
    {"id": 177, "cat": "ensenanza", "cita": "Proverbs 4:23", "libro": "Proverbs", "texto": "Keep thy heart with all diligence; for out of it are the issues of life."},
    {"id": 178, "cat": "ensenanza", "cita": "Proverbs 12:22", "libro": "Proverbs", "texto": "Lying lips are abomination to the LORD : but they that deal truly are his delight."},
    {"id": 179, "cat": "ensenanza", "cita": "Proverbs 14:12", "libro": "Proverbs", "texto": "There is a way which seemeth right unto a man, but the end thereof are the ways of death."},
    {"id": 180, "cat": "ensenanza", "cita": "Proverbs 17:17", "libro": "Proverbs", "texto": "A friend loveth at all times, and a brother is born for adversity."},
    {"id": 181, "cat": "ensenanza", "cita": "Proverbs 18:10", "libro": "Proverbs", "texto": "The name of the LORD is a strong tower: the righteous runneth into it, and is safe."},
    {"id": 182, "cat": "ensenanza", "cita": "Proverbs 20:1", "libro": "Proverbs", "texto": "Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise."},
    {"id": 183, "cat": "ensenanza", "cita": "Proverbs 28:13", "libro": "Proverbs", "texto": "He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy."},
    {"id": 184, "cat": "ensenanza", "cita": "Ecclesiastes 12:13", "libro": "Ecclesiastes", "texto": "Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man."},
    {"id": 185, "cat": "ensenanza", "cita": "Ecclesiastes 12:1", "libro": "Ecclesiastes", "texto": "Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;"},
    {"id": 186, "cat": "ensenanza", "cita": "Ecclesiastes 3:1", "libro": "Ecclesiastes", "texto": "To every thing there is a season, and a time to every purpose under the heaven:"},
    {"id": 187, "cat": "ensenanza", "cita": "Ecclesiastes 9:5", "libro": "Ecclesiastes", "texto": "For the living know that they shall die: but the dead know not any thing, neither have they any more a reward; for the memory of them is forgotten."},
    {"id": 188, "cat": "ensenanza", "cita": "Genesis 1:1", "libro": "Genesis", "texto": "In the beginning God created the heaven and the earth."},
    {"id": 189, "cat": "ensenanza", "cita": "Genesis 1:27", "libro": "Genesis", "texto": "So God created man in his own image, in the image of God created he him; male and female created he them."},
    {"id": 190, "cat": "ensenanza", "cita": "Genesis 2:3", "libro": "Genesis", "texto": "And God blessed the seventh day, and sanctified it: because that in it he had rested from all his work which God created and made."},
    {"id": 191, "cat": "ensenanza", "cita": "Exodus 20:8", "libro": "Exodus", "texto": "Remember the sabbath day, to keep it holy."},
    {"id": 192, "cat": "ensenanza", "cita": "Exodus 20:11", "libro": "Exodus", "texto": "For in six days the LORD made heaven and earth, the sea, and all that in them is , and rested the seventh day: wherefore the LORD blessed the sabbath day, and hallowed it."},
    {"id": 193, "cat": "ensenanza", "cita": "Ezekiel 20:12", "libro": "Ezekiel", "texto": "Moreover also I gave them my sabbaths, to be a sign between me and them, that they might know that I am the LORD that sanctify them."},
    {"id": 194, "cat": "ensenanza", "cita": "Ezekiel 20:20", "libro": "Ezekiel", "texto": "And hallow my sabbaths; and they shall be a sign between me and you, that ye may know that I am the LORD your God."},
    {"id": 195, "cat": "ensenanza", "cita": "Isaiah 66:23", "libro": "Isaiah", "texto": "And it shall come to pass, that from one new moon to another, and from one sabbath to another, shall all flesh come to worship before me, saith the LORD ."},
    {"id": 196, "cat": "ensenanza", "cita": "Luke 4:16", "libro": "Luke", "texto": "And he came to Nazareth, where he had been brought up: and, as his custom was, he went into the synagogue on the sabbath day, and stood up for to read."},
    {"id": 197, "cat": "ensenanza", "cita": "Hebrews 4:9", "libro": "Hebrews", "texto": "There remaineth therefore a rest to the people of God."},
    {"id": 198, "cat": "ensenanza", "cita": "1 Corinthians 6:19", "libro": "1 Corinthians", "texto": "What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?"},
    {"id": 199, "cat": "ensenanza", "cita": "1 Corinthians 10:31", "libro": "1 Corinthians", "texto": "Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God."},
    {"id": 200, "cat": "ensenanza", "cita": "3 John 1:2", "libro": "3 John", "texto": "Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth."},
    {"id": 201, "cat": "ensenanza", "cita": "Daniel 1:8", "libro": "Daniel", "texto": "But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."},
    {"id": 202, "cat": "ensenanza", "cita": "Romans 12:1", "libro": "Romans", "texto": "I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service."},
    {"id": 203, "cat": "ensenanza", "cita": "Romans 12:2", "libro": "Romans", "texto": "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God."},
    {"id": 204, "cat": "ensenanza", "cita": "Romans 3:23", "libro": "Romans", "texto": "For all have sinned, and come short of the glory of God;"},
    {"id": 205, "cat": "ensenanza", "cita": "Romans 10:17", "libro": "Romans", "texto": "So then faith cometh by hearing, and hearing by the word of God."},
    {"id": 206, "cat": "ensenanza", "cita": "Romans 1:16", "libro": "Romans", "texto": "For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek."},
    {"id": 207, "cat": "ensenanza", "cita": "Ephesians 2:8", "libro": "Ephesians", "texto": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"},
    {"id": 208, "cat": "ensenanza", "cita": "Ephesians 4:32", "libro": "Ephesians", "texto": "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you."},
    {"id": 209, "cat": "ensenanza", "cita": "Ephesians 6:1", "libro": "Ephesians", "texto": "Children, obey your parents in the Lord: for this is right."},
    {"id": 210, "cat": "ensenanza", "cita": "Colossians 3:20", "libro": "Colossians", "texto": "Children, obey your parents in all things: for this is well pleasing unto the Lord."},
    {"id": 211, "cat": "ensenanza", "cita": "Galatians 6:7", "libro": "Galatians", "texto": "Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap."},
    {"id": 212, "cat": "ensenanza", "cita": "Hebrews 11:6", "libro": "Hebrews", "texto": "But without faith it is impossible to please him : for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him."},
    {"id": 213, "cat": "ensenanza", "cita": "James 1:5", "libro": "James", "texto": "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."},
    {"id": 214, "cat": "ensenanza", "cita": "James 1:22", "libro": "James", "texto": "But be ye doers of the word, and not hearers only, deceiving your own selves."},
    {"id": 215, "cat": "ensenanza", "cita": "James 4:7", "libro": "James", "texto": "Submit yourselves therefore to God. Resist the devil, and he will flee from you."},
    {"id": 216, "cat": "ensenanza", "cita": "1 John 1:9", "libro": "1 John", "texto": "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."},
    {"id": 217, "cat": "ensenanza", "cita": "1 John 4:8", "libro": "1 John", "texto": "He that loveth not knoweth not God; for God is love."},
    {"id": 218, "cat": "ensenanza", "cita": "1 John 5:3", "libro": "1 John", "texto": "For this is the love of God, that we keep his commandments: and his commandments are not grievous."},
    {"id": 219, "cat": "ensenanza", "cita": "2 Timothy 3:16", "libro": "2 Timothy", "texto": "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:"},
    {"id": 220, "cat": "ensenanza", "cita": "Psalms 119:105", "libro": "Psalms", "texto": "Thy word is a lamp unto my feet, and a light unto my path."},
    {"id": 221, "cat": "ensenanza", "cita": "Psalms 119:11", "libro": "Psalms", "texto": "Thy word have I hid in mine heart, that I might not sin against thee."},
    {"id": 222, "cat": "ensenanza", "cita": "Psalms 51:10", "libro": "Psalms", "texto": "Create in me a clean heart, O God; and renew a right spirit within me."},
    {"id": 223, "cat": "ensenanza", "cita": "Micah 6:8", "libro": "Micah", "texto": "He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"},
    {"id": 224, "cat": "ensenanza", "cita": "Isaiah 8:20", "libro": "Isaiah", "texto": "To the law and to the testimony: if they speak not according to this word, it is because there is no light in them."},
    {"id": 225, "cat": "ensenanza", "cita": "Isaiah 1:18", "libro": "Isaiah", "texto": "Come now, and let us reason together, saith the LORD : though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool."},
    {"id": 226, "cat": "ensenanza", "cita": "2 Chronicles 7:14", "libro": "2 Chronicles", "texto": "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land."},
    {"id": 227, "cat": "ensenanza", "cita": "Amos 3:7", "libro": "Amos", "texto": "Surely the Lord GOD will do nothing, but he revealeth his secret unto his servants the prophets."},
    {"id": 228, "cat": "ensenanza", "cita": "Revelation 12:17", "libro": "Revelation", "texto": "And the dragon was wroth with the woman, and went to make war with the remnant of her seed, which keep the commandments of God, and have the testimony of Jesus Christ."},
    {"id": 229, "cat": "ensenanza", "cita": "Revelation 14:7", "libro": "Revelation", "texto": "Saying with a loud voice, Fear God, and give glory to him; for the hour of his judgment is come: and worship him that made heaven, and earth, and the sea, and the fountains of waters."},
    {"id": 230, "cat": "ensenanza", "cita": "Acts 5:29", "libro": "Acts", "texto": "Then Peter and the other apostles answered and said, We ought to obey God rather than men."},
    {"id": 231, "cat": "ensenanza", "cita": "Acts 4:12", "libro": "Acts", "texto": "Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved."},
    {"id": 232, "cat": "ensenanza", "cita": "Acts 16:31", "libro": "Acts", "texto": "And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house."},
    {"id": 233, "cat": "ensenanza", "cita": "Philippians 4:13", "libro": "Philippians", "texto": "I can do all things through Christ which strengtheneth me."},
    {"id": 234, "cat": "ensenanza", "cita": "1 Timothy 4:12", "libro": "1 Timothy", "texto": "Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity."},
    {"id": 235, "cat": "ensenanza", "cita": "John 1:1", "libro": "John", "texto": "In the beginning was the Word, and the Word was with God, and the Word was God."},
    {"id": 236, "cat": "jesus", "cita": "John 3:16", "libro": "John", "texto": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."},
    {"id": 237, "cat": "jesus", "cita": "John 14:6", "libro": "John", "texto": "Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me."},
    {"id": 238, "cat": "jesus", "cita": "John 14:1", "libro": "John", "texto": "Let not your heart be troubled: ye believe in God, believe also in me."},
    {"id": 239, "cat": "jesus", "cita": "John 14:3", "libro": "John", "texto": "And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also."},
    {"id": 240, "cat": "jesus", "cita": "John 14:15", "libro": "John", "texto": "If ye love me, keep my commandments."},
    {"id": 241, "cat": "jesus", "cita": "John 14:27", "libro": "John", "texto": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."},
    {"id": 242, "cat": "jesus", "cita": "John 16:33", "libro": "John", "texto": "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world."},
    {"id": 243, "cat": "jesus", "cita": "John 8:12", "libro": "John", "texto": "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life."},
    {"id": 244, "cat": "jesus", "cita": "John 8:32", "libro": "John", "texto": "And ye shall know the truth, and the truth shall make you free."},
    {"id": 245, "cat": "jesus", "cita": "John 6:35", "libro": "John", "texto": "And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst."},
    {"id": 246, "cat": "jesus", "cita": "John 10:10", "libro": "John", "texto": "The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly."},
    {"id": 247, "cat": "jesus", "cita": "John 10:11", "libro": "John", "texto": "I am the good shepherd: the good shepherd giveth his life for the sheep."},
    {"id": 248, "cat": "jesus", "cita": "John 10:27", "libro": "John", "texto": "My sheep hear my voice, and I know them, and they follow me:"},
    {"id": 249, "cat": "jesus", "cita": "John 11:25", "libro": "John", "texto": "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"},
    {"id": 250, "cat": "jesus", "cita": "John 13:34", "libro": "John", "texto": "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another."},
    {"id": 251, "cat": "jesus", "cita": "John 13:35", "libro": "John", "texto": "By this shall all men know that ye are my disciples, if ye have love one to another."},
    {"id": 252, "cat": "jesus", "cita": "John 15:5", "libro": "John", "texto": "I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing."},
    {"id": 253, "cat": "jesus", "cita": "John 15:12", "libro": "John", "texto": "This is my commandment, That ye love one another, as I have loved you."},
    {"id": 254, "cat": "jesus", "cita": "John 15:13", "libro": "John", "texto": "Greater love hath no man than this, that a man lay down his life for his friends."},
    {"id": 255, "cat": "jesus", "cita": "John 15:11", "libro": "John", "texto": "These things have I spoken unto you, that my joy might remain in you, and that your joy might be full."},
    {"id": 256, "cat": "jesus", "cita": "John 16:24", "libro": "John", "texto": "Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full."},
    {"id": 257, "cat": "jesus", "cita": "John 5:39", "libro": "John", "texto": "Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me."},
    {"id": 258, "cat": "jesus", "cita": "John 6:37", "libro": "John", "texto": "All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out."},
    {"id": 259, "cat": "jesus", "cita": "John 17:17", "libro": "John", "texto": "Sanctify them through thy truth: thy word is truth."},
    {"id": 260, "cat": "jesus", "cita": "Matthew 5:3", "libro": "Matthew", "texto": "Blessed are the poor in spirit: for theirs is the kingdom of heaven."},
    {"id": 261, "cat": "jesus", "cita": "Matthew 5:4", "libro": "Matthew", "texto": "Blessed are they that mourn: for they shall be comforted."},
    {"id": 262, "cat": "jesus", "cita": "Matthew 5:5", "libro": "Matthew", "texto": "Blessed are the meek: for they shall inherit the earth."},
    {"id": 263, "cat": "jesus", "cita": "Matthew 5:6", "libro": "Matthew", "texto": "Blessed are they which do hunger and thirst after righteousness: for they shall be filled."},
    {"id": 264, "cat": "jesus", "cita": "Matthew 5:7", "libro": "Matthew", "texto": "Blessed are the merciful: for they shall obtain mercy."},
    {"id": 265, "cat": "jesus", "cita": "Matthew 5:8", "libro": "Matthew", "texto": "Blessed are the pure in heart: for they shall see God."},
    {"id": 266, "cat": "jesus", "cita": "Matthew 5:9", "libro": "Matthew", "texto": "Blessed are the peacemakers: for they shall be called the children of God."},
    {"id": 267, "cat": "jesus", "cita": "Matthew 5:14", "libro": "Matthew", "texto": "Ye are the light of the world. A city that is set on an hill cannot be hid."},
    {"id": 268, "cat": "jesus", "cita": "Matthew 5:16", "libro": "Matthew", "texto": "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."},
    {"id": 269, "cat": "jesus", "cita": "Matthew 5:44", "libro": "Matthew", "texto": "But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;"},
    {"id": 270, "cat": "jesus", "cita": "Matthew 6:33", "libro": "Matthew", "texto": "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you."},
    {"id": 271, "cat": "jesus", "cita": "Matthew 6:34", "libro": "Matthew", "texto": "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof."},
    {"id": 272, "cat": "jesus", "cita": "Matthew 6:9", "libro": "Matthew", "texto": "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name."},
    {"id": 273, "cat": "jesus", "cita": "Matthew 7:7", "libro": "Matthew", "texto": "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:"},
    {"id": 274, "cat": "jesus", "cita": "Matthew 7:12", "libro": "Matthew", "texto": "Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets."},
    {"id": 275, "cat": "jesus", "cita": "Matthew 11:28", "libro": "Matthew", "texto": "Come unto me, all ye that labour and are heavy laden, and I will give you rest."},
    {"id": 276, "cat": "jesus", "cita": "Matthew 11:29", "libro": "Matthew", "texto": "Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls."},
    {"id": 277, "cat": "jesus", "cita": "Matthew 18:20", "libro": "Matthew", "texto": "For where two or three are gathered together in my name, there am I in the midst of them."},
    {"id": 278, "cat": "jesus", "cita": "Matthew 19:14", "libro": "Matthew", "texto": "But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven."},
    {"id": 279, "cat": "jesus", "cita": "Matthew 22:37", "libro": "Matthew", "texto": "Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind."},
    {"id": 280, "cat": "jesus", "cita": "Matthew 22:39", "libro": "Matthew", "texto": "And the second is like unto it, Thou shalt love thy neighbour as thyself."},
    {"id": 281, "cat": "jesus", "cita": "Matthew 24:14", "libro": "Matthew", "texto": "And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come."},
    {"id": 282, "cat": "jesus", "cita": "Matthew 24:44", "libro": "Matthew", "texto": "Therefore be ye also ready: for in such an hour as ye think not the Son of man cometh."},
    {"id": 283, "cat": "jesus", "cita": "Matthew 24:35", "libro": "Matthew", "texto": "Heaven and earth shall pass away, but my words shall not pass away."},
    {"id": 284, "cat": "jesus", "cita": "Matthew 28:19", "libro": "Matthew", "texto": "Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"},
    {"id": 285, "cat": "jesus", "cita": "Matthew 28:20", "libro": "Matthew", "texto": "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen."},
    {"id": 286, "cat": "jesus", "cita": "Matthew 4:4", "libro": "Matthew", "texto": "But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God."},
    {"id": 287, "cat": "jesus", "cita": "Matthew 25:40", "libro": "Matthew", "texto": "And the King shall answer and say unto them, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me."},
    {"id": 288, "cat": "jesus", "cita": "Mark 2:27", "libro": "Mark", "texto": "And he said unto them, The sabbath was made for man, and not man for the sabbath:"},
    {"id": 289, "cat": "jesus", "cita": "Mark 9:23", "libro": "Mark", "texto": "Jesus said unto him, If thou canst believe, all things are possible to him that believeth."},
    {"id": 290, "cat": "jesus", "cita": "Mark 10:27", "libro": "Mark", "texto": "And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible."},
    {"id": 291, "cat": "jesus", "cita": "Mark 16:15", "libro": "Mark", "texto": "And he said unto them, Go ye into all the world, and preach the gospel to every creature."},
    {"id": 292, "cat": "jesus", "cita": "Luke 6:31", "libro": "Luke", "texto": "And as ye would that men should do to you, do ye also to them likewise."},
    {"id": 293, "cat": "jesus", "cita": "Luke 6:38", "libro": "Luke", "texto": "Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again."},
    {"id": 294, "cat": "jesus", "cita": "Luke 19:10", "libro": "Luke", "texto": "For the Son of man is come to seek and to save that which was lost."},
    {"id": 295, "cat": "jesus", "cita": "Luke 15:10", "libro": "Luke", "texto": "Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth."},
    {"id": 296, "cat": "jesus", "cita": "Revelation 3:20", "libro": "Revelation", "texto": "Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me."},
    {"id": 297, "cat": "jesus", "cita": "Revelation 22:12", "libro": "Revelation", "texto": "And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be."},
    {"id": 298, "cat": "jesus", "cita": "Revelation 22:13", "libro": "Revelation", "texto": "I am Alpha and Omega, the beginning and the end, the first and the last."},
    {"id": 299, "cat": "jesus", "cita": "John 4:14", "libro": "John", "texto": "But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life."},
    {"id": 300, "cat": "jesus", "cita": "Matthew 24:42", "libro": "Matthew", "texto": "Watch therefore: for ye know not what hour your Lord doth come."}
  ]
};
